// Episode data + shared helpers. Timeline/eventos are generated by tools/maquinista_voz.py and tools/maquinista_som.py
// (voice words, camera keys resolved on words, heartbeats, barks, lever pulls, sparks, silence, freeze).
// To switch episodes, change 'ep3' in the imports of dados.ts, camera.ts, camadas.tsx and Video.tsx.
import * as THREE from 'three';
import TL from './ep3/timeline.json';
import EV from './ep3/eventos.json';

export const EP = 'ep3';
export type Palavra = {w: string; a: number; b: number; linha: string; quem: string};
export type Chave = {pose: string; t: number; move: 'cut' | 'travel' | 'whip' | 'fly'; dur?: number; roll?: number;
  creep?: number; kick?: number; flash?: number; tag?: 'insert' | 'volta' | 'montagem' | 'final' | 'take';
  /** reused clean take (public/takes/<clip>.mp4): shows that episode's time t - delta; clip_f0 = its first frame */
  clip?: string; delta?: number; clip_f0?: number; clip_ate?: number};
type Ev = {keys: Chave[]; kicks: [number, number][]; puxadas: number[]; solta: number; batidas: number[];
  latidos: [number, number][]; contagem: number; duracao: number; titulo_ate: number; congela?: number; fim_som?: number;
  silencios?: [number, number][]; faiscas?: [number, number, number][]; trem?: {v0: number; a: number; z_fim: number}};
const E = EV as unknown as Ev;
export const PALAVRAS = TL.palavras as Palavra[];
export const ROTEIRO = TL as unknown as {titulo: string; trilho_a: string; trilho_b: string; pergunta: string; contagem: number};
export const CHAVES = E.keys.slice().sort((a, b) => a.t - b.t);
export const KICKS = E.kicks;
export const PUXADAS = E.puxadas;
export const SOLTA = E.solta;
export const BATIDAS = E.batidas;
export const LATIDOS = E.latidos;
export const CONTAGEM = E.contagem;
export const DUR = E.duracao;
export const TITULO_ATE = E.titulo_ate;
export const CONGELA = E.congela ?? DUR;     // the picture freezes here (train inches from the switch)
export const FIM_SOM = E.fim_som ?? DUR;     // hard silence after this
export const SILENCIOS = E.silencios ?? [];
export const FAISCAS = E.faiscas ?? [];
const TREM = E.trem ?? {v0: 22, a: 0.2, z_fim: 0.6};

export const cl = (x: number, a = 0, b = 1) => Math.min(b, Math.max(a, x));
export const smooth = (u: number) => { u = cl(u); return u * u * (3 - 2 * u); };
/** kit ease: soft start, velocity peak at ~40 % of the move, longer settle */
export const ease40 = (u: number) => smooth(Math.pow(cl(u), 0.756));
export const V = (x: number, y: number, z: number) => new THREE.Vector3(x, y, z);
export const rng = (seed: number) => () => { seed |= 0; seed = (seed + 0x6d2b79f5) | 0; let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
  t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };

export type Pose = {p: THREE.Vector3; l: THREE.Vector3; fov: number};
export const P = (p: THREE.Vector3, l: THREE.Vector3, fov: number): Pose => ({p, l, fov});
export const add = (a: THREE.Vector3, x: number, y: number, z: number) => a.clone().add(V(x, y, z));

/** train speed (m/s): no brakes, accelerating downhill */
export const velocidade = (t: number) => TREM.v0 + TREM.a * Math.min(t, CONGELA);
/** train front z over time: z_fim metres before the switch (z = 0) when the picture freezes */
export const ZF = (t: number) => { const u = Math.min(t, CONGELA);
  return TREM.z_fim + TREM.v0 * (CONGELA - u) + (TREM.a / 2) * (CONGELA * CONGELA - u * u); };
/** metres left to the switch (distance HUD) */
export const distancia = (t: number) => Math.max(0, ZF(t));
/** track centre x: main line on z >= 0, branch A (side -1, viewer left) / B (+1) after the fork */
export const ramoX = (lado: number, z: number) => (z >= 0 ? 0 : lado * 4 * smooth(-z / 26));
export const TRILHO_Y = 0.32;  // top of the sleepers: feet of whoever stands on the track
export const PLACA_A = V(-8.5, 0, -9);
export const PLACA_B = V(8.5, 0, -9);
// inside the cab (relative to the train front)
export const CAB_Z = 7.6, PISO = 1.55;
export const cabeca = (t: number) => V(0.4, 3.13, ZF(t) + CAB_Z);
export const freio = (t: number) => V(-0.3, 2.42, ZF(t) + 6.1);   // brake knob at rest
export const desvio = (t: number) => V(-1.0, 2.57, ZF(t) + 6.6);  // switch knob

/** words said by a person (mouth open while each word plays) */
export const falando = (quem: string, t: number) => PALAVRAS.some((w) => w.quem === quem && t >= w.a && t < Math.max(w.a + 0.08, w.b - 0.04));
export const palavra = (nome: string, n = 1) => { let k = 0; for (const w of PALAVRAS) if (w.w.replace(/[.,!?;:]/g, '') === nome && ++k === n) return w.a; return -1; };
/** heartbeat envelope 0..1 (sharp hit, fast decay) */
export const pulso = (t: number) => { let e = 0; for (const b of BATIDAS) { if (b > t) break; e = Math.max(e, Math.exp(-(t - b) / 0.11)); } return e; };
/** spark intensity 0..1 at t */
export const faisca = (t: number) => FAISCAS.reduce((m, [a, b, i]) => (t >= a && t < b ? Math.max(m, i) : m), 0);
/** key active at t (last key whose time has come) */
export const chaveEm = (t: number) => { let c = CHAVES[0]; for (const k of CHAVES) if (k.t <= t) c = k; return c; };
